#!/usr/bin/env bash
# Vendor this ci-kit into a target repository as a pinned copy:
#   ops/ci/kit/   exact copy of the kit (do not edit)
#   ops/ci/kit.pin  version and content hash the copy must match
# Usage: vendor.sh <target-repo-root>
set -euo pipefail
kit_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# shellcheck source=ops/ci-kit/bin/manifest.sh
source "${kit_dir}/bin/manifest.sh"

if [[ $# -ne 1 ]]; then
  printf 'usage: %s <target-repo-root>\n' "$0" >&2
  exit 2
fi
target_root="$(cd "$1" && pwd)"
dest="${target_root}/ops/ci/kit"
pin="${target_root}/ops/ci/kit.pin"

# Refuse to vendor an unsealed kit: the canonical manifest must match content.
if ! diff -q <(ci_kit_manifest "${kit_dir}") "${kit_dir}/${CI_KIT_MANIFEST}" >/dev/null 2>&1; then
  printf 'ci-kit: canonical kit is not sealed; run %s/bin/seal.sh\n' "${kit_dir}" >&2
  exit 1
fi
if [[ "${dest}" == "${kit_dir}" ]]; then
  printf 'ci-kit: refusing to vendor the kit onto itself\n' >&2
  exit 1
fi

version="$(<"${kit_dir}/VERSION")"
hash="$(ci_kit_hash "${kit_dir}")"
staging="${target_root}/ops/ci/.kit.staging"
rm -rf -- "${staging:?}"
mkdir -p "${staging}"
cp -a "${kit_dir}/." "${staging}/"
rm -rf -- "${dest:?}"
mv -- "${staging}" "${dest}"
cat > "${pin}" <<PIN
# Generated by jeryu-ci-runner ops/ci-kit/bin/vendor.sh; do not edit.
# Check with: bash ops/ci/kit/bin/verify.sh .
source=jeryu-ci-runner:ops/ci-kit
version=${version}
sha256=${hash}
PIN
printf 'vendored ci-kit %s (sha256=%s) into %s\n' "${version}" "${hash}" "${target_root}"
